command:
// Foundry VTT Macro: Фикс фаз Active Effects (system.* -> "apply")
// Проходит по всем Item-компендиумам dedrel.* и всем изменениям (changes)
// эффектов: каждому изменению с ключом system.* и фазой, отличной от "apply",
// проставляет каноническую фазу "apply" (конвенция системы — хук
// preCreateActiveEffect делает это автоматически при обычном создании,
// но данные, импортированные макросами из JSON, хук обходили).
// См. FOUNDRY V14 QUIRKS.md §12. Перед запуском рекомендуется прогнать
// data_validation_macro.js, после — прогнать его же для контроля.
(async () => {
  const packs = game.packs.filter(p => p.documentName === "Item" && p.collection.startsWith("dedrel."));
  if (!packs.length) return ui.notifications.error("Item-компендиумы dedrel.* не найдены.");

  ui.notifications.info(`Фикс фаз: сканирую ${packs.length} компендиумов...`);

  // --- Проход 1: план правок (ничего не пишем) ---
  // plan: pack -> Map(itemId -> { item, updates: [{_id, ...}], log: [строки] })
  const plan = new Map();
  for (const pack of packs) {
    const docs = await pack.getDocuments();
    for (const item of docs) {
      for (const eff of item.effects) {
        const update = { _id: eff.id };
        const log = [];

        // V14: системные фазы живут в effect.system.changes; на всякий случай
        // правим и legacy-массив effect.changes, если там есть system.*-ключи
        for (const [path, arr] of [["system.changes", eff.system?.changes], ["changes", eff.changes]]) {
          if (!Array.isArray(arr) || !arr.length) continue;
          const fixed = foundry.utils.deepClone(arr);
          let dirty = false;
          for (const ch of fixed) {
            if (ch?.key?.startsWith("system.") && ch.phase !== "apply") {
              log.push(`${item.name} / «${eff.name}»: ${ch.key} — фаза «${ch.phase ?? "нет"}» -> «apply»`);
              ch.phase = "apply";
              dirty = true;
            }
          }
          if (dirty) update[path] = fixed;
        }

        if (log.length) {
          if (!plan.has(pack)) plan.set(pack, new Map());
          const byItem = plan.get(pack);
          if (!byItem.has(item.id)) byItem.set(item.id, { item, updates: [], log: [] });
          byItem.get(item.id).updates.push(update);
          byItem.get(item.id).log.push(...log);
        }
      }
    }
  }

  const allLog = [...plan.values()].flatMap(byItem => [...byItem.values()].flatMap(e => e.log));
  if (!allLog.length) return ui.notifications.info("Фикс фаз: все system.*-изменения уже имеют фазу «apply». Править нечего.");

  // --- Подтверждение ---
  const confirmed = await foundry.applications.api.DialogV2.confirm({
    window: { title: "Фикс фаз Active Effects" },
    content: `
      <p>Будет исправлено <b>${allLog.length}</b> изменений в эффектах:</p>
      <div style="max-height:300px;overflow-y:auto;font-size:12px;border:1px solid #999;padding:4px;">
        ${allLog.map(l => `<div>${l}</div>`).join("")}
      </div>
      <p>Компендиумы будут временно разблокированы. Продолжить?</p>
    `,
    rejectClose: false
  });
  if (!confirmed) return ui.notifications.warn("Фикс фаз отменён.");

  // --- Проход 2: запись ---
  let fixedItems = 0;
  for (const [pack, byItem] of plan) {
    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({ locked: false });
    try {
      for (const { item, updates } of byItem.values()) {
        await item.updateEmbeddedDocuments("ActiveEffect", updates);
        fixedItems++;
      }
    } finally {
      if (wasLocked) await pack.configure({ locked: true });
    }
  }

  const content = `
    <h3>Фикс фаз Active Effects</h3>
    <p>Исправлено изменений: <b>${allLog.length}</b> (предметов: ${fixedItems}).</p>
    <div style="font-size:12px;">${allLog.map(l => `<div>${l}</div>`).join("")}</div>
    <p><i>Прогоните data_validation_macro.js для контроля.</i></p>
  `;
  await ChatMessage.create({ user: game.user.id, content, whisper: [game.user.id] });
  console.log("Dedrel | Фикс фаз:", allLog);
  ui.notifications.info(`Фикс фаз: исправлено ${allLog.length} изменений в ${fixedItems} предметах.`);
})();
